Layout.Stylesheet:
@font-face { font-family: "Crimson"; font-weight: 400; src: url("CrimsonPro-Regular.ttf"); }
@font-face { font-family: "Crimson"; font-weight: 700; src: url("CrimsonPro-Bold.ttf"); }
@font-face { font-family: "Crimson"; font-weight: 400; font-style: italic; src: url("CrimsonPro-Italic.ttf"); }
@font-face { font-family: "OnlyBold"; font-weight: 900; src: url("CrimsonPro-Bold.ttf"); }
.c { font-family: "Crimson"; }
.onlybold { font-family: "OnlyBold"; }
Paragraph.onlybold { font-family: "OnlyBold"; }
